const raw = $input.first().json;
const body = raw.body || raw;
const jobId = body.jobId || '';
const fileUrl = body.fileUrl || '';
const callbackUrl = body.callbackUrl || '';
const callbackSecret = body.callbackSecret || '';
const kml_content = body.kml_content || null;
const kml_url = fileUrl || body.kml_url || null;
// O worker do app envia os campos soltos (nomeImovel, municipio, estado, rua);
// chamadas manuais podem usar params.* ou os nomes antigos (nome_terreno, uf).
const nome_terreno = body.params?.nomeImovel || body.nomeImovel || body.nome_terreno || 'Terreno';
const municipio = body.params?.municipio || body.municipio || 'Município não informado';
const uf = body.params?.estado || body.estado || body.uf || 'SP';
const rua = String(body.params?.rua || body.rua || '').trim();
const confrontantes = body.confrontantes || {};

if (!kml_content && !kml_url) {
  throw new Error('Forneça kml_content (string XML) ou kml_url (URL do arquivo KML)');
}

return {
  kml_content,
  kml_url,
  jobId,
  callbackUrl,
  callbackSecret,
  nome_terreno,
  municipio,
  uf,
  rua,
  confrontantes
};

const items = $input.all();

function extractKmlText(item) {
  const j = item.json || {};
  if (typeof j.kml_content === 'string' && j.kml_content.includes('<coordinates>')) return j.kml_content;
  if (typeof j.body === 'string' && j.body.includes('<coordinates>')) return j.body;
  if (typeof j.data === 'string' && j.data.includes('<coordinates>')) return j.data;
  return null;
}

let kmlText = null;
for (const item of items) {
  kmlText = extractKmlText(item);
  if (kmlText) break;
}

if (!kmlText) {
  throw new Error('Nenhum conteudo KML valido encontrado (kml_content ou resultado de kml_url)');
}

const coordRegex = /<coordinates>([^<]+)<\/coordinates>/g;
const matches = [...kmlText.matchAll(coordRegex)];

if (matches.length === 0) {
  throw new Error('Nenhuma tag <coordinates> encontrada no KML');
}

const coordText = matches[0][1].trim();
const points = coordText.split(/\s+/).filter(c => c.length > 0);
const coordinates = points.map(point => {
  const [lon, lat, elev] = point.split(',').map(Number);
  return { lon, lat, elev: elev || 0 };
});

return {
  coordinates,
  numPoints: coordinates.length
};

const { coordinates } = $input.first().json;
const { lon: centralLon, lat: centralLat } = coordinates[0];

// Fuso UTM: formula padrao (valida globalmente, inclusive para todas as zonas do Brasil)
const fuso = Math.floor((centralLon + 180) / 6) + 1;
const isSouth = centralLat < 0;
const falseNorthing = isSouth ? 10000000 : 0;

// Conversao WGS84/SIRGAS2000 (elipsoide GRS80) para UTM
function wgs84ToUTM(lat, lon, fuso) {
  const k0 = 0.9996;
  const a = 6378137;
  const e2 = 0.00669438;

  const lonOrigin = fuso * 6 - 183;
  const dLon = (lon - lonOrigin) * Math.PI / 180;
  const latRad = lat * Math.PI / 180;

  const n = a / Math.sqrt(1 - e2 * Math.sin(latRad) ** 2);
  const t = Math.tan(latRad) ** 2;
  const c = e2 / (1 - e2) * Math.cos(latRad) ** 2;
  const a_ = Math.cos(latRad) * dLon;

  const m = a * ((1 - e2/4 - 3*e2*e2/64 - 5*e2*e2*e2/256)*latRad -
    (3*e2/8 + 3*e2*e2/32 + 45*e2*e2*e2/1024)*Math.sin(2*latRad) +
    (15*e2*e2/256 + 45*e2*e2*e2/1024)*Math.sin(4*latRad) -
    (35*e2*e2*e2/3072)*Math.sin(6*latRad));

  const easting = k0 * n * (a_ + a_*a_*a_/6 * (1-t+c) + a_*a_*a_*a_*a_/120 * (5 - 18*t + t*t + 72*c - 58*(e2/(1-e2)))) + 500000;
  const northing = k0 * (m + n * Math.tan(latRad) * (a_*a_/2 + a_*a_*a_*a_/24 * (5 - t + 9*c + 4*c*c) + a_*a_*a_*a_*a_*a_/720 * (61 - 58*t + t*t + 600*c - 330*(e2/(1-e2))))) + falseNorthing;

  return { easting, northing };
}

const vertices = coordinates.map((coord, idx) => {
  const { easting, northing } = wgs84ToUTM(coord.lat, coord.lon, fuso);
  return {
    label: `P-${String(idx + 1).padStart(2, '0')}`,
    lat: parseFloat(coord.lat.toFixed(6)),
    lon: parseFloat(coord.lon.toFixed(6)),
    utm_e: parseFloat(easting.toFixed(2)),
    utm_n: parseFloat(northing.toFixed(2))
  };
});

const segmentos = [];
for (let i = 0; i < vertices.length; i++) {
  const p1 = vertices[i];
  const p2 = vertices[(i + 1) % vertices.length];

  const dE = p2.utm_e - p1.utm_e;
  const dN = p2.utm_n - p1.utm_n;
  const distancia = Math.sqrt(dE*dE + dN*dN);

  let azimute = Math.atan2(dE, dN) * 180 / Math.PI;
  if (azimute < 0) azimute += 360;

  const graus = Math.floor(azimute);
  const minDecimal = (azimute - graus) * 60;
  const minutos = Math.floor(minDecimal);
  const segundos = (minDecimal - minutos) * 60;

  const azimuteSex = `${graus.toString().padStart(3, '0')}°${minutos.toString().padStart(2, '0')}'${segundos.toFixed(0).padStart(2, '0')}\"`;

  segmentos.push({
    de: p1.label,
    ate: p2.label,
    azimute: azimuteSex,
    distancia_m: parseFloat(distancia.toFixed(2)),
    confrontante: ''
  });
}

let area = 0;
for (let i = 0; i < vertices.length; i++) {
  const v1 = vertices[i];
  const v2 = vertices[(i + 1) % vertices.length];
  area += (v1.utm_e * v2.utm_n - v2.utm_e * v1.utm_n);
}
area = Math.abs(area) / 2;

const perimetro = segmentos.reduce((sum, seg) => sum + seg.distancia_m, 0);

return {
  vertices,
  segmentos,
  area_m2: parseFloat(area.toFixed(2)),
  perimetro_m: parseFloat(perimetro.toFixed(2)),
  fuso_utm: `${fuso}${isSouth ? 'S' : 'N'}`
};

const skillItem = $('Carregar Skill').first().json;
const skill = skillItem.data || skillItem.body || (typeof skillItem === 'string' ? skillItem : JSON.stringify(skillItem));
const geometry = $('Calcular Geometria').first().json;
const input = $('Normalizar Input').first().json;

// Rua de frente informada pelo usuário no upload; vazia => memorial sem logradouro
const rua = String(input.rua || '').trim();

const confrontantesText = Object.entries(input.confrontantes || {})
  .map(([dir, nome]) => `${dir}: ${nome}`)
  .join('; ') || 'nao informados';

const verticesJson = JSON.stringify(geometry.vertices, null, 2);
const segmentosJson = JSON.stringify(geometry.segmentos, null, 2);

const linhaRua = rua
  ? `- Logradouro de frente (informado pelo usuario): ${rua}\n`
  : '';
const instrucaoRua = rua
  ? `\n\nIMPORTANTE: inicie o cabecalho de identificacao situando o imovel no logradouro informado (ex.: "Imovel situado na(o) ${rua}, ${input.municipio}/${input.uf}"), logo no inicio do memorial, e trate esse logradouro como a frente do imovel. Nao abrevie o tipo do logradouro e nao invente numero predial.`
  : '';

const prompt = `Gere o memorial descritivo completo para o seguinte terreno.\n\nDados calculados:\n- Nome: ${input.nome_terreno}\n${linhaRua}- Municipio/UF: ${input.municipio}/${input.uf}\n- Area: ${geometry.area_m2} m2\n- Perimetro: ${geometry.perimetro_m} m\n- Datum: SIRGAS 2000 - Fuso ${geometry.fuso_utm}\n- Vertices UTM: ${verticesJson}\n- Segmentos: ${segmentosJson}\n- Confrontantes informados: ${confrontantesText}${instrucaoRua}\n\nRetorne APENAS JSON valido (sem markdown, sem \`\`\`), com os campos: memorial_descritivo, area_m2, perimetro_m, vertices, segmentos, datum, fuso_utm.`;

return {
  prompt,
  skill,
  geometry,
  logradouro: rua
};

const aiOutput = $input.first().json;
const geometry = $('Calcular Geometria').first().json;

const rawText = aiOutput.output || aiOutput.text || aiOutput.content || '';
const cleaned = String(rawText).replace(/```json\s*/gi, '').replace(/```/g, '').trim();

let memorial_json = {};
try {
  memorial_json = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Falha ao parsear resposta JSON da IA: ' + e.message + ' | Conteudo: ' + cleaned.slice(0, 300));
}

if (!memorial_json.memorial_descritivo) {
  throw new Error('Campo memorial_descritivo ausente na resposta');
}

if (!memorial_json.descricao_perimetro) memorial_json.descricao_perimetro = '';
if (!memorial_json.vertices) memorial_json.vertices = geometry.vertices;
if (!memorial_json.segmentos) memorial_json.segmentos = geometry.segmentos;
if (!memorial_json.area_m2) memorial_json.area_m2 = geometry.area_m2;
if (!memorial_json.perimetro_m) memorial_json.perimetro_m = geometry.perimetro_m;
if (!memorial_json.fuso_utm) memorial_json.fuso_utm = geometry.fuso_utm;
if (!memorial_json.datum) memorial_json.datum = 'SIRGAS 2000';
if (!memorial_json.logradouro) memorial_json.logradouro = $('Montar Prompt IA').first().json.logradouro || '';

return memorial_json;

